import numba
from numba import jit, types
import numpy as np

# Define div_usecase
@jit(types.complex128(types.complex128, types.complex128), nopython=True)
def div_usecase(x, y):
    return x / y

# Test a critical division case from the bug report
test_cases = [
    (complex(float('-inf'), float('nan')), complex(-0.0, float('-inf'))),  # The reported case
    (complex(float('inf'), float('inf')), complex(float('inf'), 0.0)),  # inf/inf
    (complex(1e200, 1e200), complex(1e-200, 1e-200)),  # underflow case
]

for x, y in test_cases:
    try:
        result = div_usecase(x, y)
        probe('div_result_real', result.real)
        probe('div_result_imag', result.imag)
    except ZeroDivisionError:
        probe('div_zero_error', 1.0)
    except Exception as e:
        probe('div_error', 0.0)
